          PC1: { kind: 'host', ip: '10.27.1.10', mask: '255.255.255.0', gw: '10.27.1.1' }, PC3: { kind: 'host', ip: '10.27.3.10', mask: '255.255.255.0', gw: '10.27.3.1' }, PC4: { kind: 'host', ip: '10.27.4.10', mask: '255.255.255.0', gw: '10.27.4.1' }
